using HRIS.Api.Common; using HRIS.Api.DTOs.Declaration; using HRIS.Api.Exceptions; using HRIS.Api.Models; using HRIS.Api.Repositories;
namespace HRIS.Api.Services; public class DeclarationService:IDeclarationService { private readonly IDeclarationRepository _repo; private readonly IReferenceRepository _refs; private readonly IEmployeeRepository _employees; private readonly IAuditLogService _audit; public DeclarationService(IDeclarationRepository repo,IReferenceRepository refs,IEmployeeRepository employees,IAuditLogService audit){_repo=repo;_refs=refs;_employees=employees;_audit=audit;} public async Task<List<DeclarationTemplateResponseDto>> GetTemplatesAsync(bool includeInactive=false)=>(await _repo.GetTemplatesAsync(includeInactive)).Select(x=>new DeclarationTemplateResponseDto{Id=x.Id,Title=x.Title,Content=x.Content,IsActive=x.IsActive}).ToList(); public async Task<DeclarationTemplateResponseDto> SaveTemplateAsync(int id,DeclarationTemplateCreateDto dto,UserContext actor){if(!actor.IsHrOrSupport)throw new ForbiddenException("Hanya HR/Support yang boleh mengelola template deklarasi.");DeclarationTemplate x;if(id==0)x=await _repo.AddTemplateAsync(new DeclarationTemplate{Title=dto.Title.Trim(),Content=dto.Content.Trim()});else{x=await _repo.GetTemplateByIdAsync(id)??throw new NotFoundException("Template deklarasi tidak ditemukan.");x.Title=dto.Title.Trim();x.Content=dto.Content.Trim();await _repo.UpdateTemplateAsync(x);}var result=new DeclarationTemplateResponseDto{Id=x.Id,Title=x.Title,Content=x.Content,IsActive=x.IsActive};if(actor.IsSupport)await _audit.LogAsync(actor.UserId,id==0?"DeclarationTemplate.Create":"DeclarationTemplate.Update",nameof(DeclarationTemplate),x.Id,x.Title);return result;} public async Task<List<DeclarationSubmissionResponseDto>> GetSubmissionsAsync(UserContext actor)=>(await _repo.GetSubmissionsAsync(actor.IsHrOrSupport?null:actor.EmployeeId)).Select(x=>new DeclarationSubmissionResponseDto{Id=x.Id,TemplateId=x.TemplateId,TemplateTitle=x.Template?.Title??"",EmployeeId=x.EmployeeId,EmployeeName=x.Employee?.FullName??"",AgreedAt=x.AgreedAt,DocumentId=x.DocumentId}).ToList(); public async Task<DeclarationSubmissionResponseDto> SubmitAsync(int templateId,int? documentId,UserContext actor){var emp=actor.EmployeeId??throw new ForbiddenException("Akun ini tidak terhubung ke Employee.");var t=await _repo.GetTemplateByIdAsync(templateId)??throw new BadRequestException("Template deklarasi tidak ditemukan.");if(!t.IsActive)throw new BadRequestException("Template deklarasi tidak aktif.");if(documentId is not null&&!await _refs.ExistsAsync<Document>(documentId.Value))throw new BadRequestException("DocumentId tidak ditemukan.");var x=await _repo.AddSubmissionAsync(new DeclarationSubmission{TemplateId=templateId,EmployeeId=emp,DocumentId=documentId,AgreedAt=DateTime.UtcNow});var employee=await _employees.GetByIdAsync(emp);return new DeclarationSubmissionResponseDto{Id=x.Id,TemplateId=x.TemplateId,TemplateTitle=t.Title,EmployeeId=x.EmployeeId,EmployeeName=employee?.FullName??"",AgreedAt=x.AgreedAt,DocumentId=x.DocumentId};} }
